// Actual component, CareerProvider, Worker authentication and isolated D1. Fictional data only.
import {build} from 'esbuild';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';
import {createServer} from 'node:http';
import {fileURLToPath} from 'node:url';
import {migrationSchema} from '../../scripts/recovery-status.mjs';
import {validateWorkspace} from '../../worker/career-validation.js';
const root=fileURLToPath(new URL('../../',import.meta.url)),origin='http://127.0.0.1:5211';
const bundle=await build({entryPoints:[root+'worker/index.js'],bundle:true,write:false,format:'esm',platform:'browser',conditions:['workerd','worker','browser'],external:['cloudflare:*','node:*'],target:'es2022'});
const mf=new Miniflare(convertV4MiniflareOptions({modules:true,script:bundle.outputFiles[0].text,compatibilityDate:'2026-10-04',compatibilityFlags:['nodejs_compat'],cf:false,d1Databases:{DB:'fictional-batch-browser'},bindings:{AUTH_SECRET:crypto.randomUUID()+crypto.randomUUID(),APP_ORIGIN:origin},outboundService:()=>{throw Error('No external action permitted');}}));
const db=await mf.getD1Database('DB');for(const type of ['table','index','view','trigger']){const statements=migrationSchema().objects.filter(x=>x.type===type).map(x=>db.prepare(x.sql));if(statements.length)await db.batch(statements);}
const headers={Origin:origin,'Content-Type':'application/json','X-SI-Metrics':'exclude','CF-Connecting-IP':'198.51.100.141'};
const signup=await mf.dispatchFetch(origin+'/api/auth/sign-up/email',{method:'POST',headers,body:JSON.stringify({name:'Fictional batch applicant',email:'fictional-batch-browser@example.invalid',password:crypto.randomUUID()})});
if(signup.status!==200)throw Error('Fictional sign up failed');const user=(await signup.json()).user,cookies=signup.headers.getSetCookie();headers.Cookie=cookies.map(x=>x.split(';')[0]).join('; ');
const description='Use Python, SQL and clear communication to analyse data. Experience in data analysis is essential. This is a fictional example and not a real job.';
const data=validateWorkspace({version:2,profile:{name:'Fictional Applicant',email:'fictional@example.invalid',cv:'Used Python and SQL to analyse a fictional classroom dataset. Built a practice dashboard in Excel in 2024. No real applicant or customer data.'},applications:[{id:'fictional-analyst',jobId:'a'.repeat(24),company:'Fictional Harbour',title:'Data Analyst',location:'Cardiff',description,url:'https://example.invalid/jobs/analyst',sponsorship:'not_stated',stage:'Saved'},{id:'fictional-trainee',jobId:'manual-'+crypto.randomUUID(),company:'Fictional Garden',title:'Graduate Trainee',location:'Sheffield',description,url:'https://example.invalid/jobs/trainee',sponsorship:'not_stated',stage:'Saved'}],searches:[]});
const a=data.applications[0],now=new Date().toISOString();await db.prepare('INSERT INTO jobs(id,board_id,provider,company,title,location,description,apply_url,sponsorship,evidence,level,first_seen,last_seen,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1)').bind(a.jobId,'fictional','fictional',a.company,a.title,a.location,a.description,a.url,a.sponsorship,'','not_stated',now,now).run();
const saved=await mf.dispatchFetch(origin+'/api/career/workspace',{method:'PUT',headers,body:JSON.stringify({accountId:user.id,revision:0,data})});if(saved.status!==200)throw Error('Fictional workspace failed');
const ui=await build({stdin:{contents:`import React from 'react';import {createRoot} from 'react-dom/client';import {CareerProvider,useCareer} from './src/career-data';import {ApplicationBatches} from './src/application-batches';import './src/styles.css';import './src/career.css';
function Preview(){const c=useCareer();return <main style={{maxWidth:1000,margin:'20px auto',padding:12}}><h1>Fictional application batch</h1><p>Local test account. No employer, AI or email service is connected.</p><div className="batch-actions"><button onClick={()=>c.setData(d=>({...d,profile:{...d.profile,cv:d.profile.cv+' New fictional experience.'}}))}>Fictional: edit CV</button><button onClick={()=>fetch('/fixture/close-role',{method:'POST'})}>Fictional: close role</button><button onClick={()=>fetch('/fixture/uncertain',{method:'POST'})}>Fictional: lose next reply</button><button onClick={()=>c.logout()}>Fictional: sign out</button></div><ApplicationBatches go={view=>document.getElementById('destination').textContent=view}/><p id="destination"/></main>;}createRoot(document.getElementById('root')).render(<CareerProvider><Preview/></CareerProvider>);`,resolveDir:root,loader:'tsx'},bundle:true,write:false,format:'esm',platform:'browser',outfile:'fixture.js',define:{'process.env.NODE_ENV':'"production"'}});
const assets=new Map(ui.outputFiles.map(f=>[f.path.split('/').pop(),f.contents]));let loseReply=false;
const server=createServer(async(req,res)=>{try{
 const url=new URL(req.url,origin);let response;
 if(url.pathname==='/fixture/close-role'&&req.method==='POST'){await db.prepare('UPDATE jobs SET active=0').run();response=new Response('closed');}
 else if(url.pathname==='/fixture/uncertain'&&req.method==='POST'){loseReply=true;response=new Response('next reply will be lost');}
 else if(url.pathname.startsWith('/api/')){const chunks=[];for await(const chunk of req)chunks.push(chunk);const body=Buffer.concat(chunks);response=await mf.dispatchFetch(url.href,{method:req.method,headers:{...req.headers,'X-SI-Metrics':'exclude','CF-Connecting-IP':'198.51.100.141'},...(body.length?{body}:{}),redirect:'manual'});if(loseReply&&url.pathname.startsWith('/api/career/batches')&&req.method==='POST'){loseReply=false;response=Response.json({error:'Fictional lost reply after save'},{status:503});}}
 if(response){res.writeHead(response.status,Object.fromEntries(response.headers));return res.end(Buffer.from(await response.arrayBuffer()));}
 if(url.pathname==='/'){res.writeHead(200,{'Content-Type':'text/html','Set-Cookie':cookies});return res.end('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fictional application batches</title><link rel="stylesheet" href="/fixture.css"></head><body><div id="root"></div><script type="module" src="/fixture.js"></script></body></html>');}
 if(assets.has(url.pathname.slice(1))){res.writeHead(200,{'Content-Type':url.pathname.endsWith('.css')?'text/css':'application/javascript'});return res.end(assets.get(url.pathname.slice(1)));}res.writeHead(404);res.end('Not a fixture route');
 }catch(e){console.error(e.message);res.writeHead(500);res.end('Local fixture error');}});
server.listen(5211,'127.0.0.1',()=>console.log('Fictional actual Worker preview: '+origin));
process.on('SIGINT',async()=>{server.close();await mf.dispose();process.exit(0);});
